[
  {
    "rawId": "sugar-verified-chinimandi",
    "evidenceIds": [
      "news-92d04a3dfa9943ec22f1"
    ],
    "title": "인도 석유마케팅기업(OMC), 2026-27 에탄올 공급 연도(ESY) 입찰 개시",
    "summary": "인도 석유마케팅기업(OMCs)이 2026-27 에탄올 공급 연도(ESY) 1차 입찰을 통해 약 1100 크로어(110억) 리터 규모의 변성 무수 에탄올 공급자를 모집합니다. 정부 방침에 따라 2026-27 ESY 기간 동안 에탄올 생산을 위한 설탕 전용(Sugar diversion)이 제로(0)로 설정되어, 사탕수수 즙, 설탕, 설탕 시럽 및 B-중당밀을 원료로 한 에탄올은 입찰 대상에서 제외되었습니다. 공급 가능 원료는 C-중당밀, 손상 곡물, 인도식량공사(FCI) 조달 잉여 쌀, 옥수수 및 기타 국가 바이오연료 정책(NPB) 지정 원료로 한정됩니다. 납품 기간은 2026년 11월 1일부터 2027년 10월 31일까지이며, 현재 진행 중인 관련 사법 절차 결과에 따라 할당량이 수정되거나 취소될 수 있는 조건이 포함되어 있습니다."
  }
]

[
  {
    "rawId": "corn-feed-commodity-board.com-19",
    "evidenceIds": ["news-dcb2f62982f9773fbf35", "news-408581c17878d739efb9", "news-7126fcba96becb81bbd6", "news-404d4c7617368f4e6880", "news-8d197d4337c1dceb1570", "news-550a40a140dd5397c949"],
    "title": "인도 옥수수 시장, 신곡 출하에도 공급 부족 및 가격 강세 지속",
    "summary": "인도 옥수수 시장은 신곡 수확에도 불구하고 타이트한 수급 기조를 이어가고 있습니다. 흉작으로 인한 생산량 감소와 곡물 크기 저하, 강력한 에탄올 및 사료 수요가 시장을 지지하고 있으며, 운송 비용 상승까지 겹쳐 가격 강세가 지속되는 모습입니다. 시장 참여자들은 공급 제약이 계속될 경우 퀴탈당 약 2.12달러의 추가 가격 상승 가능성을 언급하고 있습니다. 품질 격차도 확대되어 비하르산 고품질 옥수수는 높은 가격을 형성하고 있습니다. 조달 담당자는 정부의 에탄올 정책과 피드백 수요를 주시하며 물량을 확보하되, 고점 매수를 경계하는 신중한 접근이 권장됩니다."
  },
  {
    "rawId": "corn-index-ahdb.org.uk-0",
    "evidenceIds": ["news-8aba7e3cc9e644778598", "news-09b32855ae353a90a65d", "news-28c22667d2b952437d89", "news-5a1f002a3b7dde5e5d37"],
    "title": "글로벌 곡물 시장 하락세, 미국 옥수수 수확 진전에 따른 가격 압력",
    "summary": "최근 글로벌 곡물 시장은 공급 전망 개선과 미국 내 빠른 옥수수 수확 진전에 힘입어 하락세를 보였습니다. 시카고 옥수수 선물은 3.9% 하락했으며, 이러한 가격 압력은 미국 중서부 지역의 양호한 수확 날씨와 함께 당분간 지속될 것으로 보입니다. 흑해 지역의 지정학적 불안 요인이 존재하지만, 전반적인 수확 진행 상황이 가격 하락을 견인하고 있습니다."
  },
  {
    "rawId": "corn-feed-commodity-board.com-28",
    "evidenceIds": ["news-685a266a21825bdf18d4", "news-820c196761dc161cddcd", "news-ebfef04c5f2e45ef6c5d", "news-96eb39a63ec1d33a2d1f", "news-a693b1fbeac6c756b5fb", "news-7987c168d396467c4a8a", "news-378802090bbde70dacc7", "news-7e8db9d3f11c3019c43e"],
    "title": "유럽 옥수수 작황 부진 심화, 흑해 공급이 가격 하방 지지",
    "summary": "2026년 유럽연합(EU)의 옥수수 수확량은 5년 평균 대비 9% 감소했으며, 특히 헝가리, 프랑스, 독일의 피해가 큽니다. 프랑스의 경우 옥수수 생산량이 지난 50년 중 최저 수준으로 예상됩니다. 반면 동남부 유럽과 흑해 지역의 작황은 상대적으로 양호하여 시장 수급을 보완하고 있습니다. 유로넥스트 옥수수 선물은 공급 부족으로 인해 강보합세를 보이나, 경쟁력 있는 흑해산 옥수수 공급이 가격 급등을 억제하고 있습니다. 조달 측면에서는 독일, 프랑스 등 서유럽 지역의 타이트한 수급을 고려하여 흑해 및 동남부 EU 원산지 위주의 점진적인 물량 확보 전략이 필요합니다."
  },
  {
    "rawId": "corn-index-grains.org-0",
    "evidenceIds": ["news-215985287c3164a866d9", "news-936a3e4890627a2ac530", "news-5c0954e025a1c437f79c"],
    "title": "미국 옥수수 선물 가격 약세 및 운송 지표 변동",
    "summary": "10월 22일 기준 시카고 옥수수 선물 가격은 주간 단위로 하락세를 기록했습니다. 미국산 황색 옥수수(Yellow Corn)의 FOB 가격은 11월 인도분 기준 걸프만(Gulf) 221.44달러, PNW 236.80달러 수준을 형성하고 있습니다. 발틱 운임 지수(Baltic Dry) 등 해상 운송 비용은 품목별로 1~30%의 변동성을 보이고 있어, 원산지별 수입 전략 수립 시 물류비용과 시장 스프레드 확인이 필수적입니다."
  },
  {
    "rawId": "corn-ers-oct26",
    "evidenceIds": ["news-2cff7282f79866fc727c", "news-a608291857d8584eb1ef", "news-1eded6866748b255427f", "news-0252a3be802c0955ca64", "news-59ecb715f9b8ec50235f", "news-9063ddf8ccfb9441a5f0", "news-c83ea1e4869faca2600d", "news-ddd8e4c228fd9d7b9b5e", "news-68fc8bbff492cdaf2418", "news-00b96d0649b481717b92", "news-8f64485390ac45bda214", "news-1b2baf7c4d167124ea66", "news-41e69b8cbf23671b468f", "news-545259630e7060d99e3e", "news-85b2fcde17ccec8f2eae"],
    "title": "미국 옥수수 생산량 상향 조정 및 2026/27 수급 전망",
    "summary": "USDA의 10월 보고서에 따르면 2026/27 마케팅 연도 미국 옥수수 생산량은 수확량 상향 조정으로 전월 대비 1,030만 톤 증가하여 역대 두 번째 규모를 기록할 전망입니다. 미국 기말 재고량 역시 2억 8,200만 부셸 늘어난 18억 부셸로 상향되었습니다. 한편, 에탄올용 옥수수 수요는 가솔린 대비 가격 경쟁력과 캘리포니아 E15 법안으로 인해 전년 대비 증가세입니다. 반면 EU의 옥수수 생산량은 기상 악화로 전년 대비 16% 감소할 것으로 보여, 글로벌 수급의 지역적 불균형이 심화될 것으로 보입니다."
  },
  {
    "rawId": "corn-feed-commodity-board.com-49",
    "evidenceIds": ["news-09dc76dc64c275818357", "news-50187901b363c9bb6052", "news-7bd31621aef60625f546", "news-c76114c1cebfbc72ed16", "news-31d44c25d9ff6e2527ab", "news-9fe3c8c8ecaa00768e9e", "news-e12ad8a5d0da78cb7764"],
    "title": "미국 수확 가속화 및 수출 부진으로 옥수수 가격 하방 압력 지속",
    "summary": "미국 내 옥수수 수확이 빠르게 진행되면서 가용 공급량이 증가하고, 미국 수출 판매 부진과 우크라이나의 물류 제한 속 경쟁적인 흑해산 공급이 시장 가격을 압박하고 있습니다. 유럽 현물 가격과 선물 가격도 동반 하락세를 보이고 있습니다. 미국 옥수수 수출량은 작년 대비 34% 낮은 수준을 기록 중입니다. 시장 전문가들은 당분간 가격 하락 또는 횡보세가 이어질 것으로 예상하며, EU의 사료 구매자들에게는 현재의 가격 약세를 활용하여 내년 1분기~2분기까지 물량을 확보할 것을 제언합니다."
  }
]

[
  {
    "rawId": "procurement-tapioca",
    "evidenceIds": [
      "news-ec18ed83d0163424a41e"
    ],
    "title": "2026년 10월 카사바 및 타피오카 전분 시장 동향",
    "summary": "2026년 10월 19일 기준, 베트남 타피오카 전분 수출 가격은 FOB 호치민 기준 톤당 610~650달러, 랑선(Lang Son) 도착도 기준 톤당 4,100~4,250위안 수준입니다. 건조 카사바 칩 수출가는 중국향 톤당 265달러, 한국향 톤당 320달러를 기록했습니다. FOB 기준 타피오카 전분 가격은 전주 대비 톤당 약 10달러 하락했습니다. 중국 시장 내 베트남산 타피오카 전분은 톤당 4,500~4,800위안, 태국산은 4,900~5,500위안에 거래되고 있습니다. 시장은 전반적인 상승세보다 관망세가 짙으며, 구매자는 향후 중국의 수요 회복 여부와 카사바 원물 가격, 물류 비용 및 품질 조건을 면밀히 모니터링하여 조달 계획을 수립해야 합니다."
  },
  {
    "rawId": "live-tapioca-starch-0",
    "evidenceIds": [
      "news-cd0dd155e824a152d8e1"
    ],
    "title": "원물 공급 부족으로 인한 베트남 카사바 가격 상승",
    "summary": "카사바 모자이크병으로 인한 수확량 감소와 재배 면적 축소로 원물 공급이 부족해지면서 베트남 카사바 수출 가격이 높은 수준을 유지하고 있습니다. 2026년 9월 말 기준, 베트남 타피오카 전분 수출 가격은 FOB 호치민 기준 톤당 610~630달러입니다. 중국 시장 내 재고량은 전년 동기 대비 76% 감소하며 공급 긴장감을 높이고 있습니다. 2026년 1~7월 누적 기준 베트남의 대(對)중국 카사바 제품 수출량은 196만 톤, 수출액은 6억 8,880만 달러를 기록했습니다. 한편, 한국으로의 수출은 전년 동기 대비 176.3% 증가한 2만 5,800톤으로 급성장했습니다. 원재료 수급 불균형이 심화됨에 따라 향후 조달 시 시장 변동성에 유의가 필요합니다."
  }
]

[
  {
    "rawId": "rss-commodity-board.com-0",
    "evidenceIds": ["news-f9b09bfb6400b66eaf31"],
    "title": "인도 밀 시장, 정부 경매와 명절 수요로 혼조세",
    "summary": "인도 밀 시장은 정부의 조기 경매 물량과 제분소의 수요가 맞물리며 지역별로 혼조세를 보이고 있습니다. 명절인 디왈리를 앞두고 일부 지역에서는 구매가 활발해 가격이 지지받고 있으나, 정부의 충분한 비축량과 e-경매가 가격 상승을 제한하고 있습니다. 2026년 10월 23일 기준 국제 밀 가격은 미국산(단백질 11.5%) 0.22 EUR/kg, 프랑스산(단백질 11.0%) 0.29 EUR/kg, 우크라이나산(단백질 11.0%) 0.107 EUR/kg 등으로 전반적으로 안정적인 수준을 유지하고 있습니다."
  },
  {
    "rawId": "rss-commodity-board.com-48",
    "evidenceIds": ["news-8b15c8a871f76b12eb35"],
    "title": "글로벌 밀 선물 가격, 풍부한 공급과 지정학적 완화 기대에 하락세",
    "summary": "전 세계 밀 시장은 충분한 공급량과 흑해 지역의 평화 협상 가능성으로 인해 리스크 프리미엄이 축소되면서 가격 하락 압력을 받고 있습니다. CBOT 등 주요 거래소의 밀 선물은 수주째 하락세를 이어가고 있으며, 우크라이나산 밀(단백질 11.0%)의 FOB 가격은 10월 초 0.122 EUR/kg에서 10월 23일 0.107 EUR/kg으로 하락했습니다. 주요 산지의 양호한 기상 여건과 대규모 수확 전망이 향후에도 가격 하락 압력으로 작용할 것으로 보입니다."
  },
  {
    "rawId": "wheat-index-ahdb.org.uk-0",
    "evidenceIds": ["news-029e4b0f7380fec3c3ca"],
    "title": "글로벌 밀 공급 개선 및 아르헨티나 수확량 상향 조정",
    "summary": "글로벌 밀 시장은 미국 내 양호한 수확 진행과 공급 개선 기대감으로 하락세를 보이고 있습니다. 영국산 사료용 밀(11월물)은 193.75 GBP/t으로 마감하며 전주 대비 11.25 GBP/t 하락했습니다. 특히 로사리오 곡물거래소는 아르헨티나의 2026/27 시즌 밀 수확량 전망치를 기존 2,100만 톤에서 2,380만 톤으로 상향 조정했으며, 이는 역대 두 번째로 많은 생산량으로 전 세계 밀 공급량 증가에 기여할 것으로 예상됩니다."
  },
  {
    "rawId": "rss-world-grain.com-4",
    "evidenceIds": ["news-c973f67a705bb8adfede"],
    "title": "호주, 유전자 변형(GM) 밀 품종 규제 검토 진행",
    "summary": "호주·뉴질랜드 식품기준청(FSANZ)은 멜버른 대학교가 개발한 두 가지 GM 밀 품종(UM-12115T-1)의 판매 및 사용 허가 신청에 대한 공개 의견 수렴을 시작했습니다. 해당 GM 밀은 철분과 아연 흡수를 돕는 니코티아나민 함량을 높인 것이 특징이며, 주로 사료용으로 의도되었으나 향후 식품 공급망에 진입할 가능성도 있습니다. 당국은 해당 GM 밀의 인체 안전성에 우려가 없다고 평가했으며, 2026년 12월 1일까지 의견을 수렴한 후 최종 승인 여부를 결정할 예정입니다."
  },
  {
    "rawId": "wheat-index-uswheat.org-1",
    "evidenceIds": ["news-37aac7bb8c87b4b91269"],
    "title": "나이지리아 제분업계, 미국산 밀 활용을 통한 파스타 생산 효율화 모색",
    "summary": "나이지리아 2위 제분업체인 올람(Olam)의 관계자가 미국 노스다코타주 노던 크롭스 인스티튜트(NCI)에서 미국산 밀(HRS, HRW, SRW)을 활용한 파스타 생산 기술 교육을 받았습니다. 이는 미국 밀 협회(USW)의 후원으로 진행되었으며, 나이지리아 제분업계가 미국산 밀의 다양한 등급을 블렌딩하여 원가 경쟁력을 확보하고 제품 품질을 개선하는 데 목적이 있습니다."
  },
  {
